      if (this.newApp && !this.user.apps.includes(this.newApp)) {
        this.user.apps.push(this.newApp)
        this.newApp = ''
      }
    },
    removeApp(index) {
      this.user.apps.splice(index, 1)
    }
  }
}
</script>
