    </div>
  </div>
</template>

<script>
export default {
  props: ['user'],
  data() {
    return {
      saving: false
    }
  },
  computed: {
    rules() {
      if (!this.user.token_limit_rules) this.user.token_limit_rules = []
      return this.user.token_limit_rules
    },
    allRequests() {
      return (this.user.token_limit_requests || []).map(r => ({ ...r, _adminNote: r._adminNote || '' }))
    },
    pendingRequests() {
      return this.allRequests.filter(r => r.status === 'pending')
    }
  },
  methods: {
    addRule() {
      if (!this.user.token_limit_rules) this.user.token_limit_rules = []
      this.user.token_limit_rules.push({
        model: '',
        daily_limit: 100000,
        period: 'daily',
        extension: null
      })
    },
    removeRule(index) {
      this.user.token_limit_rules.splice(index, 1)
    },
    addExtension(index) {
      const today = new Date().toISOString().split('T')[0]
      this.user.token_limit_rules[index].extension = {
        date: today,
        extra_tokens: 0,
        extra_percent: 0
      }
    },
    clearExtension(index) {
      this.user.token_limit_rules[index].extension = null
    },
    // Resolve a pending request inline, saves immediately via API
    async resolveRequest(req, status) {
      try {
        await this.$storex.api.post(
          `/admin/token-limits/${this.user.username}/requests/${req.id}`,
          { status, admin_note: req._adminNote || null }
        )
        // Update local request status for instant feedback
        const match = (this.user.token_limit_requests || []).find(r => r.id === req.id)
        if (match) {
          match.status = status
          match.admin_note = req._adminNote || null
        }
      } catch (e) {
        console.error('Failed to resolve request', e)
      }
    },
    requestCardClass(status) {
      return {
        'border-warning bg-warning/10': status === 'pending',
        'border-success bg-success/10': status === 'approved',
        'border-error bg-error/10': status === 'denied',
        'border-base-300 bg-base-200': !['pending','approved','denied'].includes(status)
      }
    },
    statusBadgeClass(status) {
      return {
        'badge-warning': status === 'pending',
        'badge-success': status === 'approved',
        'badge-error': status === 'denied'
      }
    }
  }
}
</script>
